        (N'R214-82',N'Droits réels éligibles : les 7 catégories',NULL,NULL,NULL,N'12',N'1',N'CMF',NULL,NULL,N'CMF'),
        (N'R214-83',N'Éligibilité des participations : 3 conditions cumulatives',NULL,NULL,NULL,N'13',N'1',N'CMF',NULL,NULL,N'CMF'),
        (N'R214-85',N'Par dérogation à l''article R. 214-83, l''actif d''une société de placement à prépondérance immobilière à capital variable peut également comprendre des participations directes ou indirectes',NULL,NULL,NULL,N'17',N'1',N'CMF',NULL,NULL,N'CMF'),
        (N'R214-86',N'L''organisme de placement collectif immobilier doit employer au moins 20 % de ses actifs immobiliers en immeubles construits, loués ou offerts à la location.',NULL,NULL,NULL,N'18',N'1',N'CMF',NULL,NULL,N'CMF'),
        (N'R214-87',N'Pour l''appréciation de la limite de 20 % mentionnée à l''article R. 214-85 et du ratio de 20 % mentionné à l''article R. 214-86, il est tenu compte, au dénominateur',NULL,NULL,NULL,N'19',N'1',N'CMF',NULL,NULL,N'CMF'),
        (N'R214-88',N'La limite de 20 % mentionnée à l''article R. 214-85 et le ratio de 20 % mentionné à l''article R. 214-86 sont respectés le 30 juin et le 31 décembre de chaque exercice',NULL,NULL,NULL,N'20',N'1',N'CMF',NULL,NULL,N'CMF'),
        (N'R214-89',N'Pour l''appréciation des quotas de 60 % et 51 % mentionnés au 1° de l''article L. 214-37, il est tenu compte, au dénominateur',NULL,NULL,NULL,N'21',N'1',N'CMF',NULL,NULL,N'CMF'),
        (N'R214-90',N'Les quotas de 60 % et 51 % mentionnés au 1° de l''article L. 214-37 sont respectés le 30 juin et le 31 décembre de chaque exercice, à l''issue de la période de trois ans',NULL,NULL,NULL,N'22',N'1',N'CMF',NULL,NULL,N'CMF'),
        (N'R214-95',N'Les parts ou actions d''organismes mentionnées au 5° du I de l''article L. 214-36 peuvent représenter plus de 10 % de l''actif de l''organisme de placement collectif immobilier',NULL,NULL,NULL,N'23',N'1',N'CMF',NULL,NULL,N'CMF'),
        (N'R214-96',N'Les instruments financiers mentionnés aux 6° et 7° du I de l''article L. 214-36 et à l''article R. 214-93 émis par une même entité ne peuvent représenter plus de 10 % de l''actif',NULL,NULL,NULL,N'24',N'1',N'CMF',NULL,NULL,N'CMF'),
        (N'R214-97',N'Un organisme de placement collectif immobilier ne peut détenir plus de 20 % d''une même catégorie d''instruments financiers mentionnés aux 4°, 6° et 7° du I de l''article L. 214-36',NULL,NULL,NULL,N'25',N'1',N'CMF',NULL,NULL,N'CMF'),
        (N'R214-99',N'dépôts à terme mentionnés à l''article R. 214-92 effectués auprès d''un même établissement de crédit par l''organisme de placement collectif immobilier ne peuvent représenter plus de 20 % de son actif.',NULL,NULL,NULL,N'26',N'1',N'CMF',NULL,NULL,N'CMF');
